describe('negated and positive option order', () => {
  test.each([
    ['negated first', (p) => p.option('--no-pepper').option('--pepper')],
    ['positive first', (p) => p.option('--pepper').option('--no-pepper')],
  ])('%s: no implicit default when both defined', (_name, define) => {
    const program = new commander.Command();
    define(program);
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBeUndefined();
  });

  test.each([
    [
      'negated first',
      (p) => p.option('--no-pepper', 'remove pepper', 'plain').option('--pepper'),
    ],
    [
      'positive first',
      (p) => p.option('--pepper').option('--no-pepper', 'remove pepper', 'plain'),
    ],
  ])('%s: explicit default of negated option used', (_name, define) => {
    const program = new commander.Command();
    define(program);
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toEqual('plain');
  });

  test('lone negated option defaults to true', () => {
    const program = new commander.Command();
    program.option('--no-pepper');
    program.parse(['node', 'test']);
    expect(program.opts().pepper).toBe(true);
  });
});
